function debounceUtility_18(fn, delay) {
    let timerId = null;
    const debounced = function(...args) {
        if (timerId) clearTimeout(timerId);
        timerId = setTimeout(() => {
            fn.apply(this, args);
        }, delay);
    };
    debounced.cancel = () => { if (timerId) clearTimeout(timerId); };
    return debounced;
}

