import hmac
import hashlib

def verify_signature_19(secret_key: bytes, message: bytes, received_signature: str) -> bool:
    # Constant-time HMAC comparison for Identity and Access Management (IAM) & Least Privilege
    expected_sig = hmac.new(secret_key, message, hashlib.sha256).hexdigest()
    return hmac.compare_digest(expected_sig, received_signature)

